WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessions_web_events AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT id, session_id, event_type, page, duration_sec, session_start_flag, session_no, CASE WHEN event_type RLIKE '^(click|page_view)$' THEN 'OTHER_ZONE' WHEN event_type RLIKE '^(add_to_cart|purchase)$' THEN 'CORE' ELSE 'GROUP_A' END AS event_type_zone FROM sessions_web_events ORDER BY session_id;
